def clean_word(w):
    w = w.strip().lower()
    return w

words3 = [clean_word(w) for w in text3.split(',') if clean_word(w)]
words4 = [clean_word(w) for w in text4.split(',') if clean_word(w)]

# Filter functions
words3 = [w for w in words3 if 3 <= len(w) <= 7]
words4 = [w for w in words4 if 3 <= len(w) <= 7]

def is_too_technical(w):
    if w.endswith(('ium', 'oid', 'ae', 'itis', 'ia', 'is', 'um', 'id')):
        common = set(['acid', 'grid', 'rapid', 'about', 'across', 'basic', 'music', 'topic', 'logic', 'radio', 'audio', 'video', 'stadium', 'medium', 'basis', 'analysis', 'crisis', 'thesis', 'physics', 'classic', 'plastic', 'clinic', 'arctic', 'public', 'tonic', 'fabric', 'metric', 'static', 'magic', 'logic', 'comic', 'topic', 'cynic', 'toxic', 'relic', 'panic', 'civic', 'mimic', 'sonic', 'optic', 'ironic', 'exotic', 'static', 'tactic', 'ethics', 'rubric', 'manic', 'pulpit', 'habit', 'profit', 'spirit', 'credit', 'bandit', 'exhibit', 'deposit', 'benefit', 'deficit', 'transit', 'pundit', 'merit', 'orbit', 'visit', 'limit', 'unit', 'knit', 'exit', 'wait', 'bait', 'suit', 'fruit', 'recruit', 'circuit', 'biscuit', 'conduit', 'pursuit', 'lawsuit', 'verdict', 'predict', 'addict', 'conflict', 'restrict', 'strict', 'convict', 'depict', 'distinct', 'instinct', 'abstract', 'compact', 'contract', 'distract', 'extract', 'impact', 'intact', 'subtract', 'contact', 'retract', 'protract', 'interact', 'detract', 'attract', 'distract', 'exact', 'fact', 'tact', 'pact', 'raft', 'shaft', 'craft', 'graft', 'drift', 'shift', 'lift', 'gift', 'swift', 'theft', 'loft', 'soft', 'left', 'tuft'])
        if w in common: return False
        return True
    tech = set(['barium', 'glycids', 'glycins', 'hydroid', 'dactyli', 'fibulae', 'dudgeon', 'czarist', 'diabase', 'dialled', 'digraph', 'diploid', 'diurnal', 'dyadic', 'egoism', 'egoist', 'egress', 'effigy', 'eighths', 'elided', 'elides', 'elision', 'ellipse', 'emaciate', 'emanate', 'embayed', 'emetics', 'emirate', 'emulsoid', 'encomia', 'endemic', 'enervate', 'enrank', 'entropy', 'enzyme', 'epaulet', 'epergne', 'epigram', 'epistle', 'epithet', 'epitome', 'epsilon', 'equable', 'equerry', 'equines', 'equinox', 'errhine', 'ersatz', 'erudite', 'ethinyl', 'etude', 'eunuch', 'euphony', 'evince', 'exhalant', 'exiguous', 'exitus', 'exotica', 'exulted'])
    if w in tech: return True
    return False

clean_pool3 = [w for w in words3 if not is_too_technical(w)]
clean_pool4 = [w for w in words4 if not is_too_technical(w)]
seen = set()
unique_pool3 = [x for x in clean_pool3 if not (x in seen or seen.add(x))]
unique_pool4 = [x for x in clean_pool4 if not (x in seen or seen.add(x))]
target_total = 1500
result_pool = list(unique_pool3)
needed = target_total - len(result_pool)
if needed > 0:
    total_candidates4 = len(unique_pool4)
    step = total_candidates4 / needed
    sampled4 = [unique_pool4[int(i * step)] for i in range(needed)]
    result_pool.extend(sampled4)
final_result = []
final_seen = set()
for w in result_pool:
    if w not in final_seen:
        final_result.append(w)
        final_seen.add(w)
if len(final_result) < target_total:
    for w in unique_pool4:
        if w not in final_seen:
            final_result.append(w)
            final_seen.add(w)
            if len(final_result) == target_total: break
final_result = final_result[:1500]

dict_path = 'src/popup/dictionaries.js'
with open(dict_path, 'r', encoding='utf-8') as f:
    orig_content = f.read()
new_en_json = json.dumps(final_result, ensure_ascii=False)
pattern = r'en:\s*\[[^\]]*\],'
new_content = re.sub(pattern, f'en: {new_en_json},', orig_content)
with open(dict_path, 'w', encoding='utf-8') as f:
    f.write(new_content)
print(f'Successfully injected {len(final_result)} words into EN pool.')
